def compute(vars):
    payment_volume = vars["v1"]
    total_transactions = vars["v2"]

    if total_transactions == 0:
        return None

    value = payment_volume / total_transactions

    return {
        "value": value,
        "trace": {
            "payment_volume": payment_volume,
            "total_transactions": total_transactions,
            "calculation": "payment_volume / total_transactions",
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "USD per transaction"
            }
        }
    }

def compute(vars):
    gain_on_land_sales = vars["v1"]
    gain_on_ownership_interests = vars["v2"]

    total_gain_thousand = gain_on_land_sales + gain_on_ownership_interests
    total_gain_million = total_gain_thousand / 1000

    return {
        "value": total_gain_million,
        "trace": {
            "gain_on_land_sales_thousand": gain_on_land_sales,
            "gain_on_ownership_interests_thousand": gain_on_ownership_interests,
            "total_gain_thousand": total_gain_thousand,
            "conversion": "thousand to million by dividing by 1000",
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }

def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    if old_value == 0:
        return None

    absolute_change = new_value - old_value
    change_ratio = absolute_change / old_value
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "absolute_change": absolute_change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
